def count_range_sum(nums, lower, upper):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    candidates = set()
    for s in prefix:
        candidates.update([s, s - lower, s - upper])       # every value ever inserted or queried
    sorted_vals = sorted(candidates)
    rank = {v: i + 1 for i, v in enumerate(sorted_vals)}
    m = len(sorted_vals)
    bit = [0] * (m + 1)

    def update(i):
        while i <= m:
            bit[i] += 1
            i += i & (-i)

    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & (-i)
        return s

    count = 0
    update(rank[prefix[0]])
    for j in range(1, n + 1):
        lo_r = rank[prefix[j] - upper]                        # earlier prefixes in [prefix[j]-upper, prefix[j]-lower]
        hi_r = rank[prefix[j] - lower]
        count += query(hi_r) - query(lo_r - 1)
        update(rank[prefix[j]])
    return count

