public class Main {
    static int[] bit;
    static int m;

    static void update(int i) {
        for (; i <= m; i += i & (-i)) bit[i]++;
    }

    static int query(int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += bit[i];
        return s;
    }

    static int countRangeSum(int[] nums, long lower, long upper) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        TreeSet<Long> candidates = new TreeSet<>();
        for (long s : prefix) { candidates.add(s); candidates.add(s - lower); candidates.add(s - upper); }
        Map<Long, Integer> rank = new HashMap<>();
        int idx = 1;
        for (long v : candidates) rank.put(v, idx++);
        m = candidates.size();
        bit = new int[m + 1];

        int count = 0;
        update(rank.get(prefix[0]));
        for (int j = 1; j <= n; j++) {
            int loR = rank.get(prefix[j] - upper);              // earlier prefixes in this rank range
            int hiR = rank.get(prefix[j] - lower);
            count += query(hiR) - query(loR - 1);
            update(rank.get(prefix[j]));
        }
        return count;
    }
}

