using namespace std;

vector<int> bit;
int m;

void update(int i) { for (; i <= m; i += i & (-i)) bit[i]++; }
int query(int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; }

int countRangeSum(vector<int>& nums, long long lower, long long upper) {
    int n = nums.size();
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    vector<long long> candidates;
    for (long long s : prefix) { candidates.push_back(s); candidates.push_back(s - lower); candidates.push_back(s - upper); }
    sort(candidates.begin(), candidates.end());
    candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());
    auto rankOf = [&](long long v) {
        return (int)(lower_bound(candidates.begin(), candidates.end(), v) - candidates.begin()) + 1;
    };
    m = candidates.size();
    bit.assign(m + 1, 0);

    int count = 0;
    update(rankOf(prefix[0]));
    for (int j = 1; j <= n; j++) {
        int loR = rankOf(prefix[j] - upper);                    // earlier prefixes in this rank range
        int hiR = rankOf(prefix[j] - lower);
        count += query(hiR) - query(loR - 1);
        update(rankOf(prefix[j]));
    }
    return count;
}
